      const cs = Math.cos(phi);
      const sn = Math.sin(phi);
      let minY = 1e9;
      let idx = 0;
      A.S.forEach(function(q2, i) {
        const y = q2[0] * cs - q2[1] * sn;
        if (y < minY - 1e-6) {
          minY = y;
          idx = i;
        }
      });
      const q = A.S[idx];
      const zi = q[0] * sn + q[1] * cs;
