        const bh = m.length < 1.9 ? 0.26 : 0.32;
        c.roundBox(m.length < 1.9 ? 0.36 : 0.42, bh, 0.32, 0.03, m.length < 1.9 ? MATERIALS.wood : makeMaterial("#3d3a2e"), bxx, ry + bh / 2, 0);
        jerryCan(c, bxx, ry + bh + 0.22, 0, "#8e2a20");
        if (m.length >= 1.9)
          [1, -1].forEach(function(s2) {
            c.tube(
              [
                [0.38, 0.9, s2 * 0.18],
                [0.45, 0.6, s2 * 0.32],
                [0.1, 0.3, s2 * 0.3]
              ],
              0.02,
              MATERIALS.steel
            );
          });
