    const OLIVE_STEEL = CM("#3c4030", { metalness: 0.4, roughness: 0.6 }), CANVAS = CM("#55553c", { roughness: 0.98, side: DS }), CANVAS2 = CM("#4a4b34", { roughness: 0.98, side: DS });
